#232;re&quot;&gt;Demeure cach&#233;e (Mag)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Paria&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Paria (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Vision&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Vision (Sur)&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Cauchemars&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Cauchemars (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Emissairedelasorci&#232;re&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Emissaire de la sorci&#232;re (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Parlerenr&#234;ve&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Parler en r&#234;ve (Mag)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Voldevoix&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Vol de voix (Sur)&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Contr&#244;leduclimat&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Contr&#244;le du climat (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Faveurdelasorci&#232;re&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Faveur de la sorci&#232;re (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Peauanimale&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Peau animale (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Couvertdegivre&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Couvert de givre (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Gu&#233;risonmajeure&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Gu&#233;rison majeure (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Poup&#233;edecire&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Poup&#233;e de cire (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td CLASS=&quot;centre&quot; COLSPAN=&quot;4&quot;&gt;Grands mal&#233;fices&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Abomination&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Abomination (Mag)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Donneusedevie&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Donneuse de vie (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Mal&#233;dictionmortelle&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Mal&#233;diction mortelle (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Sinistreproph&#233;tie&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Sinistre proph&#233;tie (Sur)&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Convocationdesprit&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Convocation d’esprit (Mag)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Huttedelasorci&#232;re&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Hutte de la sorci&#232;re (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#R&#233;incarnationforc&#233;e&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;R&#233;incarnation forc&#233;e (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Sommeil&#233;ternel&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Sommeil &#233;ternel (Sur)&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#D&#233;sastrenaturel&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;D&#233;sastre naturel (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Mal&#233;dictiondenonviolence&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Mal&#233;diction de non-violence (Sur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Repos&#233;ternel&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;Repos &#233;ternel (Mag)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Mal&#233;fices&lt;a class=&quot;headeranchor&quot; id=&quot;Mal&#233;fices_63&quot; href=&quot;#Mal&#233;fices_63&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Magic/Art de la Magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Agacerlesb&#234;tes&quot; href=&quot;#Agacerlesb&#234;tes&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Agacer les b&#234;tes (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Agacer_les_b&#234;tes_Sur_0&quot; href=&quot;#Agacer_les_b&#234;tes_Sur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les animaux deviennent irritables en pr&#233;sence de la cible (Volont&#233; pour annuler). Les animaux sont inquiets et agressifs : les chevaux ruent, les chiens aboient et claquent des m&#226;choires, les taureaux chargent, etc. Le mal&#233;fice dure un nombre d’heures &#233;gal au modificateur d’Intelligence de la sorci&#232;re. Une cr&#233;ature qui r&#233;ussit son jet de sauvegarde ne peut plus &#234;tre affect&#233;e par ce mal&#233;fice pendant 1 jour. La r&#233;action des animaux est un effet mental de charme mais ce n’est pas le cas du sort lanc&#233; sur la cible.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Auradepuret&#233;&quot; href=&quot;#Auradepuret&#233;&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Aura de puret&#233; (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Aura_de_puret&#233;_Sur_1&quot; href=&quot;#Aura_de_puret&#233;_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La sorci&#232;re purifie l&#39;air autour d&#39;elle. Les &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;Les maladies&quot;&gt;maladies&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt; inhal&#233;s et effets de gaz nocifs sont annul&#233;s dans un rayon de 3 m&#232;tres (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) autour d&#39;elle pour un nombre de minutes par jour &#233;gal &#224; son niveau de sorci&#232;re. Ces minutes ne doivent pas forc&#233;ment &#234;tre cons&#233;cutives. Les effets de sorts dont le niveau est sup&#233;rieur &#224; la moiti&#233; du niveau de la sorci&#232;re ne sont pas affect&#233;s.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cercle&quot; href=&quot;#Cercle&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Cercle (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Cercle_Ext_2&quot; href=&quot;#Cercle_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
La sorci&#232;re compte comme une guenaude quand il s’agit de rejoindre un &lt;a class=&quot;pagelink&quot; href=&quot;Guenaude-Verte.html#Cercles_de_guenaudes_0&quot; title=&quot;Guenaude, Guenaude verte&quot;&gt;cercle&lt;/a&gt; de ces cr&#233;atures. Le cercle doit contenir au moins une v&#233;ritable guenaude. Quand une sorci&#232;re qui dispose de ce mal&#233;fice se trouve &#224; moins de 9 m d’une autre qui le poss&#232;de aussi, elle peut utiliser l’action &lt;a class=&quot;pagelink&quot; href=&quot;Actions%20sp%C3%A9ciales.ashx#Aider_quelqu’un_4&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;aider&lt;/a&gt; autrui pour donner &#224; l’autre un bonus de +1 au &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;Niveau de lanceur de sorts&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Ce bonus s’applique aux sorts et aux mal&#233;fices de la sorci&#232;re.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Chance&quot; href=&quot;#Chance&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Chance (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Chance_Sur_3&quot; href=&quot;#Chance_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---R&#232;gles-Avanc&#233;es.html#48&quot; title=&quot;FAQ du Manuel des joueurs - R&#232;gles avanc&#233;es&quot;&gt;→&lt;/a&gt; Sorci&#232;re, Mal&#233;fice chance : Combien de fois une cr&#233;ature peut-elle &#171; b&#233;n&#233;ficier &#187; de ce mal&#233;fice ? S&#39;il dure plus d&#39;un round, est-ce qu&#39;il se termine la premi&#232;re fois qu&#39;il est utilis&#233; ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Lorsqu&#39;une cr&#233;ature est la cible du mal&#233;fice de &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Chance&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;chance&lt;/a&gt;&lt;/u&gt;, elle gagne les avantages de ce mal&#233;fice une fois par round, jusqu&#39;&#224; ce que la dur&#233;e du mal&#233;fice se termine, comme d&#233;termin&#233; par le niveau de la sorci&#232;re &#224; l&#39;origine de l&#39;effet. Une fois termin&#233;, la cr&#233;ature ne peut plus &#234;tre la cible de ce mal&#233;fice pendant 24 heures.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
